<?php
namespace App\Http\Controllers;
use App\Collaboration\{CollaborationResourceReference,CollaborationResourceRegistry};use App\Models\Webhook;use App\Services\WebhookActivationService;use Illuminate\Http\Request;
final class WebhookActivationController extends Controller{public function __construct(private CollaborationResourceRegistry $registry,private WebhookActivationService $service){}public function state(Request $r,string $id){$w=$this->resolve($r,$id,'view');return ['data'=>['active'=>$w->enabled,'approvedRevisionId'=>$w->approved_revision_id?(string)$w->approved_revision_id:null,'approvedSubmissionId'=>$w->approved_submission_id?(string)$w->approved_submission_id:null]];}public function activate(Request $r,string $id){$w=$this->resolve($r,$id,'edit');abort_unless($w->approved_revision_id,422,'An approved revision is required.');app(\App\Services\WebhookUrlGuard::class)->assertSafe($w->approvedRevision()->firstOrFail()->snapshot['configuration']['url']);$w->update(['enabled'=>true]);return response()->json(['data'=>['active'=>true]]);}public function deactivate(Request $r,string $id){$w=$this->resolve($r,$id,'edit');$w->update(['enabled'=>false]);return response()->json(['data'=>['active'=>false]]);}public function submit(Request $r,string $id){$d=$r->validate(['revision_id'=>'required|integer']);$s=$this->service->submit($r->user(),$this->resolve($r,$id,'edit'),$d['revision_id']);return response()->json(['data'=>['id'=>(string)$s->id,'status'=>$s->status,'revisionId'=>(string)$s->submitted_revision_id]],201);}private function resolve(Request $r,string $id,string $ability):Webhook{return $this->registry->resolve($r->user(),new CollaborationResourceReference('webhook',$id),$ability)->resource;}}